1101 | /* ===== Playlist Search ===== */
1102 | 
1103 | .playlist-search-container {
1104 |   display: flex;
1105 |   align-items: center;
1106 |   gap: 4px;
1107 |   padding: 6px 8px;
1108 |   border-bottom: 1px solid var(--winamp-border);
1109 |   background: rgba(0, 0, 0, 0.1);
1110 | }
1111 | 
1112 | .playlist-search-input {
1113 |   flex: 1;
1114 |   padding: 4px 8px;
1115 |   font-family: var(--font-mono);
1116 |   font-size: 11px;
1117 |   background: var(--winamp-progress-bg);
1118 |   border: 1px solid var(--winamp-border);
1119 |   border-radius: var(--border-radius);
1120 |   color: var(--winamp-text);
1121 |   outline: none;
1122 |   transition: border-color 0.15s;
1123 | }
1124 | 
1125 | .playlist-search-input:focus {
1126 |   border-color: var(--winamp-accent-dim);
1127 |   box-shadow: 0 0 6px rgba(0, 255, 136, 0.1);
1128 | }
1129 | 
1130 | .playlist-search-input::placeholder {
1131 |   color: var(--winamp-text-dim);
1132 |   opacity: 0.6;
1133 | }
1134 | 
1135 | .playlist-search-clear {
1136 |   width: 22px;
1137 |   height: 22px;
1138 |   border: 1px solid var(--winamp-border);
1139 |   border-radius: var(--border-radius);
1140 |   background: var(--winamp-primary);
1141 |   color: var(--winamp-text-dim);
1142 |   font-size: 10px;
1143 |   cursor: pointer;
1144 |   display: flex;
1145 |   align-items: center;
1146 |   justify-content: center;
1147 |   transition: all 0.15s;
1148 |   flex-shrink: 0;
1149 |   line-height: 1;
1150 | }
1151 | 
1152 | .playlist-search-clear:hover {
1153 |   background: var(--winamp-highlight);
1154 |   border-color: var(--winamp-highlight);
1155 |   color: #fff;
1156 | }
1157 | 
1158 | .playlist-search-count {
1159 |   padding: 4px 10px;
1160 |   font-size: 10px;
1161 |   color: var(--winamp-accent);
1162 |   background: rgba(0, 255, 136, 0.06);
1163 |   border-bottom: 1px solid var(--winamp-border);
1164 |   text-align: center;
1165 |   letter-spacing: 0.5px;
1166 | }
1167 | 
1168 | /* ===== Selection ===== */
1169 | 
1170 | ::selection {
1171 |   background: var(--winamp-accent);
